// V49: decide the dashboard after sign-in (and when a signed-in person opens /login/).
async function routeSignedIn(){
 const db=await marketplaceClient();const {data:{user}}=await db.auth.getUser();if(!user)return;
 const current=new URLSearchParams(location.search);
 // Return only to a safe Hustle path after sign-in; never to an external URL.
 // V52: an explicit ?next= wins; otherwise resume the intent saved before sign-up / e-mail confirmation.
 const stored=login?takeReturnIntent():null;
 const returnPath=login?(safePostLoginPath(current.get('next'))||(current.has('service')||current.has('seller')?null:stored)):null;
 if(returnPath){window.location.replace(returnPath);return}
 const next=new URLSearchParams();
 const seller=current.get('seller');
 if(seller&&/^[a-z0-9][a-z0-9-]{2,59}$/.test(seller))next.set('seller',seller);
 const wantedService=current.get('service');if(wantedService&&/^[0-9a-f-]{36}$/.test(wantedService))next.set('service',wantedService);
 const ctx=current.get('ctx');if(seller&&ctx&&/^[0-9a-f-]{36}$/.test(ctx))next.set('ctx',ctx);
 const wantedTier=current.get('tier');if(wantedService&&(wantedTier==='Basic'||wantedTier==='Standard'||wantedTier==='Premium'))next.set('tier',wantedTier);
 const [beta,own]=await Promise.all([db.from('beta_allowlist').select('role').eq('email',(user.email||'').toLowerCase()).eq('enabled',true).maybeSingle(),db.from('profiles').select('is_seller').eq('id',user.id).maybeSingle()]);
 let last:string|null=null;try{last=localStorage.getItem(WORKSPACE_KEY)}catch{}
 const mode=chooseWorkspace({entry,login,asked:current.get('mode'),buyerIntent:next.has('seller')||next.has('service'),role:(beta.data as {role?:string}|null)?.role||'',isSeller:(own.data as {is_seller?:boolean}|null)?.is_seller===true,last});
 next.set('mode',mode);
 const ref=current.get('ref');if(ref)next.set('ref',ref);
 const destination=mode==='seller'?'/seller-studio/':mode==='admin'?'/admin/':'/buyer/';
 const target=destination+(next.toString()?'?'+next.toString():'');
 // Each page renders the dashboard for its own entry, so a different dashboard needs a real navigation.
 if(mode!==entry){window.location.replace(target);return}
 history.replaceState(null,'',target);
}
async function auth(e:FormEvent){e.preventDefault();if(register&&emailCooldown>0)return;setBusy(true);setError('');setNotice('');try{const db=await marketplaceClient();const response=register?await db.auth.signUp({email:email.trim().toLowerCase(),password,options:{emailRedirectTo:location.origin+'/login/'}}):await db.auth.signInWithPassword({email:email.trim().toLowerCase(),password});if(response.error){if(response.error.code==='email_not_confirmed'||/email not confirmed/i.test(response.error.message||''))throw new Error(t('Имэйлээ баталгаажуулаагүй байна. Ирсэн имэйл болон Спам хавтаснаас баталгаажуулах холбоосоо нээнэ үү. Имэйл ирээгүй бол доорх товчоор дахин хүсэж болно.','Your email is not confirmed. Check Inbox and Spam for Confirm your email, or resend it below.'));throw response.error;}if(register&&!response.data.session)setNotice(t('Бүртгэлийн хүсэлтийг хүлээн авлаа. Шинээр бүртгүүлж байгаа бол имэйлээ баталгаажуулаад нэвтрээрэй. Имэйл ирээгүй бол Спам хавтсаа шалгаарай.','Signup request accepted. New accounts can sign in after confirming their email—no admin approval needed. Email delivery depends on the configured provider.'));else{
 // Do not expose navigation until both the workspace data and its initial route
 // are ready: late startup work must not overwrite a conversation just opened.
 setLoading(true);
 try{
 await load();
 await routeSignedIn();
 }finally{setLoading(false)}
 }}catch(e){fail(e)}finally{setBusy(false)}}
useEffect(()=>{if(emailCooldown<=0)return;const timer=setInterval(()=>setEmailCooldown(v=>Math.max(0,v-1)),1000);return()=>clearInterval(timer)},[emailCooldown>0]);
async function resendConfirmation(){if(busy||emailCooldown>0)return;setBusy(true);setError('');setNotice('');try{if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))throw new Error(t('Эхлээд имэйл хаягаа оруулна уу.','Enter your email address first.'));const db=await marketplaceClient();const r=await db.auth.resend({type:'signup',email:email.trim().toLowerCase(),options:{emailRedirectTo:location.origin+'/login/'}});if(r.error)throw r.error;setEmailCooldown(60);setNotice(t('Хүсэлтийг хүлээн авлаа. Ирсэн имэйл болон Спам хавтсаа шалгаарай. Өмнө бүртгүүлсэн бол “Нэвтрэх” эсвэл “Нууц үг сэргээх” сонголтыг ашиглаарай.','Request accepted; email delivery is not guaranteed. Already registered? Sign in or reset your password instead.'));}catch(e){fail(e)}finally{setBusy(false)}}
async function refreshMessages(){if(!uid||!role)return;const db=await marketplaceClient();const r=await db.from('messages').select('id,sender_id,recipient_id,body,created_at,read_at').or('sender_id.eq.'+uid+',recipient_id.eq.'+uid).order('created_at',{ascending:false}).order('id',{ascending:false}).limit(500);if(r.error)throw r.error;const latest=r.data as ChatMessage[];setHasOlderMessages(latest.length===500);setMessages(previous=>mergeMessagePage(previous,latest))}
// V52: older history is paged per conversation, with a cursor taken from that thread only.
async function loadOlderMessages(peer:string=chatPeer){if(!uid||!role||!peer||olderMessagesLoading||!peerHasOlder(peer))return;const thread=threadMessages(messages,uid,peer);if(!thread.length){setOlderByPeer(m=>({...m,[peer]:false}));return}setOlderMessagesLoading(true);try{const db=await marketplaceClient();const oldest=thread[0];const r=await db.from('messages').select('id,sender_id,recipient_id,body,created_at,read_at').or('and(sender_id.eq.'+uid+',recipient_id.eq.'+peer+'),and(sender_id.eq.'+peer+',recipient_id.eq.'+uid+')').or('created_at.lt.'+oldest.created_at+',and(created_at.eq.'+oldest.created_at+',id.lt.'+oldest.id+')').order('created_at',{ascending:false}).order('id',{ascending:false}).limit(100);if(r.error)throw r.error;const older=r.data as ChatMessage[];setOlderByPeer(m=>({...m,[peer]:older.length===100}));setMessages(previous=>mergeMessagePage(previous,older))}catch(e){fail(e)}finally{setOlderMessagesLoading(false)}}
function peerHasOlder(peer:string){return olderByPeer[peer]??hasOlderMessages}
useEffect(()=>{
  if(!uid||!role)return;
  let active=true;
  let unsubscribe=()=>{};
  setRealtimeStatus('connecting');
  const sync=async()=>{
    const db=await marketplaceClient();
    const response=await db.from('messages')
      .select('id,sender_id,recipient_id,body,created_at,read_at')
      .or('sender_id.eq.'+uid+',recipient_id.eq.'+uid)
      .order('created_at',{ascending:false}).order('id',{ascending:false}).limit(500);
    if(!active||response.error)return;
    // Merge rather than overwrite events arriving while a fetch is in flight.
    setHasOlderMessages(previous=>previous||response.data.length===500);
    setMessages(existing=>{
      const own=existing.filter(message=>message.sender_id===uid||message.recipient_id===uid);
      return mergeMessagePage(own,response.data as ChatMessage[]);
    });
  };
  void marketplaceClient().then(db=>{
    if(!active)return;
    const accept=(payload:{new:Record<string,unknown>})=>{
      const message=payload.new as ChatMessage;
      if(!active||!message.id||!(message.sender_id===uid||message.recipient_id===uid))return;
      setMessages(list=>appendUniqueMessage(list,message));
    };
    const channel=db.channel('hustle-beta-inbox-'+uid)
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'recipient_id=eq.'+uid},accept)
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'sender_id=eq.'+uid},accept)
      .subscribe(status=>{
        if(!active)return;
        if(status==='SUBSCRIBED'){setRealtimeStatus('connected');void sync();}
        if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED')setRealtimeStatus('fallback');
      });
    unsubscribe=()=>{void db.removeChannel(channel)};
    void sync();
  }).catch(()=>{if(active)setRealtimeStatus('fallback')});
  // Missed network events and inactive tabs still converge on the DB.
  const interval=window.setInterval(()=>{if(active)void sync()},30000);
  return()=>{active=false;clearInterval(interval);unsubscribe()};
},[uid,role]);
function openChat(peerId:string){if(!peerId||peerId===uid)return;setChatPeer(peerId);setTab('messages');setError('');void markThreadRead(peerId)}
// A selected file is only a local draft. No upload, RPC or message is created until Send.
function stageChatFile(file:File){
 const invalid=validateChatFile(file);
 if(invalid){setError(invalid);return}
 setError('');
 setPendingChatFile(file);
}
useEffect(()=>{setPendingChatFile(null)},[uid,chatPeer]);
async function sendMessage(e:FormEvent<HTMLFormElement>){
 e.preventDefault();
 const body=normalizedMessage(chatDraft),file=pendingChatFile,recipient=chatPeer;
 if((!body&&!file)||!recipient||recipient===uid||busy||chatLoading||uploading)return;
 setChatLoading(true);setError('');
 try{
  // Upload first, then text. Clearing a successfully sent attachment before sending
  // text prevents accidental duplicate uploads if the text request fails.
  if(file){
   await attachFile(file,recipient);
   setPendingChatFile(current=>current===file?null:current);
  }
  if(body){
   const db=await marketplaceClient();
   const r=await db.from('messages').insert({sender_id:uid,recipient_id:recipient,body}).select('id,sender_id,recipient_id,body,created_at').single();
   if(r.error)throw r.error;
   setMessages(list=>appendUniqueMessage(list,r.data as ChatMessage));
   setChatDraft(current=>normalizedMessage(current)===body?'':current);
  }
 }catch(err){fail(err)}finally{setChatLoading(false)}
}
async function attachFile(file:File,recipient:string){
 const invalid=validateChatFile(file);
 if(invalid)throw new Error(invalid==='Unsupported file type'?t('Энэ төрлийн файл илгээх боломжгүй. Зураг, PDF, Office, ZIP файл илгээнэ үү.','This file type is not supported. Send images, PDF, Office or ZIP files.'):invalid==='Invalid filename'?t('Файлын нэр хэт урт байна.','The file name is too long.'):t('Файл 10 MB-аас ихгүй байх ёстой.','Files must be 10 MB or smaller.'));
 setUploading(true);
 try{
  const db=await marketplaceClient();
  const extension=file.name.split('.').pop()?.toLowerCase()||'bin';
  const path=uid+'/'+recipient+'/'+crypto.randomUUID()+'.'+extension;
  const up=await db.storage.from('chat-attachments').upload(path,file,{contentType:file.type,upsert:false});
  if(up.error)throw up.error;
  const sent=await db.rpc('send_chat_attachment',{target_recipient:recipient,upload_path:path,display_name:file.name,mime:file.type,bytes:file.size});
  if(sent.error){
   try{await db.storage.from('chat-attachments').remove([path])}catch{}
   throw sent.error;
  }
  const [m,a]=await Promise.all([
   db.from('messages').select('id,sender_id,recipient_id,body,created_at,read_at').eq('id',sent.data).single(),
   db.from('chat_attachments').select('*').eq('message_id',sent.data).single()
  ]);
  if(m.data)setMessages(list=>appendUniqueMessage(list,m.data as ChatMessage));
  if(a.data)setAttachments(list=>[...list,a.data as MessengerAttachment]);
  // The database message already succeeded; a transient UI refresh must not resend it.
  if(m.error||a.error)void refreshMessages().catch(()=>{});
 }finally{setUploading(false)}
}
