useEffect(()=>{if(!uid||!role||tab!=='messages'||!chatPeer)return;let active=true;const images=attachments.filter(a=>((a.sender_id===uid&&a.recipient_id===chatPeer)||(a.sender_id===chatPeer&&a.recipient_id===uid))&&a.content_type.startsWith('image/'));if(!images.length)return;void marketplaceClient().then(db=>Promise.all(images.map(a=>db.storage.from('chat-attachments').createSignedUrl(a.object_path,90).then(r=>({id:a.id,url:r.data?.signedUrl}))))).then(found=>{if(active)setFileUrls(old=>({...old,...Object.fromEntries(found.filter(x=>x.url).map(x=>[x.id,x.url!]))}))}).catch(()=>{});return()=>{active=false}},[uid,role,tab,chatPeer,attachments]);
useEffect(()=>{if(!uid||!role||!chatPeer||tab!=='messages')return;let active=true;void marketplaceClient().then(db=>db.rpc('seller_average_response',{target_seller:chatPeer})).then(r=>{if(active&&!r.error&&r.data)setResponseStats(old=>({...old,[chatPeer]:r.data as {samples:number;average_minutes:number|null}}))}).catch(()=>{});return()=>{active=false}},[uid,role,chatPeer,tab]);
