const submitProfile=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const slug=normalizeSellerSlug(String(f.get('slug')||''));const publicProfile=f.get('public_profile')==='on';if((slug&&!isValidSellerSlug(slug))||(publicProfile&&!isValidSellerSlug(slug))){setError(t('Профайлын хаяг 3–60 тэмдэгттэй, зөвхөн жижиг латин үсэг, тоо, зураас агуулна. Нийтэд нээх бол хаяг заавал хэрэгтэй.','The public profile URL must be 3–60 characters using lowercase letters, numbers and hyphens. A public profile requires a slug.'));return;}setSlugDraft(slug);const becameSeller=f.get('is_seller')==='on'&&!profile?.is_seller;void perform(async()=>{const r=await(await marketplaceClient()).from('profiles').upsert({id:uid,display_name:f.get('display_name'),headline:f.get('headline'),bio:f.get('bio'),skills:String(f.get('skills')||'').slice(0,400),is_seller:f.get('is_seller')==='on',slug:slug||null,public_profile:publicProfile});if(r.error){if(r.error.code==='23505')throw new Error(t('Энэ профайлын хаягийг өөр хүн ашиглаж байна. Өөр хаяг сонгоно уу.','This profile URL is already taken. Choose another.'));if(r.error.code==='23514')throw new Error(t('Профайлын хаягийн хэлбэр буруу байна. Жишээ: test-мэргэжилтэн','Invalid profile URL format. Example: test-freelancer'));throw r.error;}if(new URLSearchParams(location.search).has('seller'))entryApplied.current=false;if(becameSeller)window.location.assign('/my-profile/');},t('Профайл хадгалагдлаа.','Profile saved.'))};
