const statuses:Record<string,[string,string]>={requested:['Шинэ хүсэлт','Requested'],accepted:['Зөвшөөрсөн','Accepted'],in_progress:['Гүйцэтгэж байна','In progress'],delivered:['Хүлээлгэн өгсөн','Delivered'],completed:['Дууссан','Completed'],rejected:['Татгалзсан','Rejected'],cancelled:['Цуцлагдсан','Cancelled'],draft:['Ноорог','Draft'],pending:['Хянагдаж байна','In review'],published:['Нийтлэгдсэн','Published'],verified:['Баталгаажсан','Verified']};
